-- Publish the Pexels library catalog and let visitors read approved templates
-- without executing has_role. The catalog is fixed; the function only inserts
-- a design when that source, source id, and format are not already stored.

DROP POLICY IF EXISTS "Active templates are readable" ON public.templates;
DROP POLICY IF EXISTS "Public can view templates" ON public.templates;
DROP POLICY IF EXISTS "Templates are publicly readable" ON public.templates;
DROP POLICY IF EXISTS "Templates files readable" ON public.templates;
DROP POLICY IF EXISTS "Templates are viewable by everyone" ON public.templates;

CREATE POLICY "Approved templates are readable"
  ON public.templates
  FOR SELECT
  TO anon, authenticated
  USING (is_active AND review_status = 'approved');

CREATE POLICY "Admins can read every template"
  ON public.templates
  FOR SELECT
  TO authenticated
  USING (public.has_role(auth.uid(), 'admin'));

CREATE OR REPLACE FUNCTION public.ensure_library_templates()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  before_count integer;
  after_count integer;
BEGIN
  SELECT count(*) INTO before_count FROM public.templates;
    INSERT INTO public.templates (name, description, category, platform, objective, format, width, height, preview_url, thumbnail_url, template_json, ai_tags, industry_tags, brand_compatible, popularity_score, source, source_id, source_license, external_id, template_source, premium, is_active, is_file_based, review_status, review_note, metadata)
    SELECT 'Skincare Still Life', 'Photo by Kaboompics on Pexels.', 'Beauty', 'Instagram Story', 'Awareness', 'story', 1080, 1920, 'https://images.pexels.com/photos/4735904/pexels-photo-4735904.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/4735904/pexels-photo-4735904.jpeg?auto=compress&cs=tinysrgb&h=350', '{"version":"6.0.0","background":"#0b0b0f","width":1080,"height":1920,"objects":[{"type":"image","name":"Background image","src":"https://images.pexels.com/photos/4735904/pexels-photo-4735904.jpeg?auto=compress&cs=tinysrgb&w=1600","crossOrigin":"anonymous","left":540,"top":960,"originX":"center","originY":"center","scaleX":0.40973111395646605,"scaleY":0.40973111395646605,"selectable":true,"evented":true,"meta":{"role":"hero_image","variable":"hero_image","locked":true}},{"type":"rect","name":"Contrast scrim","left":0,"top":806.4,"width":1080,"height":1113.6,"fill":"rgba(8,8,14,0.62)","selectable":true,"meta":{"role":"scrim"}},{"type":"textbox","name":"Headline","text":"{{headline}}","left":86,"top":1075,"width":908,"fontSize":76,"fontWeight":"700","fontFamily":"{{brand.font}}","fill":"#ffffff","editable":true,"meta":{"role":"headline","variable":"headline"}},{"type":"textbox","name":"Subheadline","text":"{{subheadline}}","left":86,"top":1382,"width":908,"fontSize":37,"fontFamily":"{{brand.font}}","fill":"rgba(255,255,255,0.86)","editable":true,"meta":{"role":"subheadline","variable":"subheadline"}},{"type":"rect","name":"CTA background","left":86,"top":1613,"width":454,"height":134,"rx":67,"ry":67,"fill":"{{brand.primaryColor}}","meta":{"role":"cta_bg"}},{"type":"textbox","name":"CTA","text":"{{cta}}","left":86,"top":1642,"width":454,"textAlign":"center","fontSize":32,"fontWeight":"600","fontFamily":"{{brand.font}}","fill":"#ffffff","editable":true,"meta":{"role":"cta","variable":"cta"}}]}'::jsonb, ARRAY['Beauty', 'story']::text[], ARRAY['Beauty']::text[], true, 40, 'pexels', '4735904', 'pexels:free', '4735904', 'pexels', false, true, false, 'approved', 'Library stock pack', '{"recommended_platforms":["Instagram Story","TikTok"],"author":"Kaboompics","page_url":"https://www.pexels.com/photo/assorted-cosmetics-on-white-surface-4735904/","stock":true}'::jsonb
